def move_knowledge_bases(apps, schema_editor):
    """A project serving a knowledge base (or ever published one) gets its `kb`
    service row with every `kb_*` field and its readers; nothing else moves."""
    AgentProject = apps.get_model("agents", "AgentProject")
    ProjectService = apps.get_model("agents", "ProjectService")
    for p in AgentProject.objects.all():
        if not (p.mcp_kind or p.kb_key or p.kb_version_id or p.kb_drive_replica):
            continue
        svc = ProjectService.objects.create(
            project=p, kind="kb", name="kb", description=p.outcome or "",
            kb_key=p.kb_key, kb_sha256=p.kb_sha256, kb_bytes=p.kb_bytes, kb_published_at=p.kb_published_at,
            kb_version_id=p.kb_version_id, kb_drive_replica=p.kb_drive_replica,
            kb_drive_replica_file_id=p.kb_drive_replica_file_id)
        svc.kb_readers.set(p.kb_readers.all())


